// 辞任不能用今日空职/人物控制替代当时真实本人和审批者；实际当面行为由本业务永久记录见证。
#pragma once
#include "political_office_resignation_rules.hpp"
#include "resident/domains/politics/politics_internal.hpp"
#include "resident/domains/family/actor_presence_read.hpp"
namespace hanmo::resident::office_resignation_detail {
inline bool closed(const PoliticalOfficeResignationState& state,const StableId& request){for(const auto& r:state.answers.rows())if(r.second.request_fact_id==request)return true;for(const auto& r:state.withdrawals.rows())if(r.second.request_fact_id==request)return true;return false;}
inline bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& ids=c.state().facts.order();auto i=std::find(ids.begin(),ids.end(),a),j=std::find(ids.begin(),ids.end(),b);return i!=ids.end()&&j!=ids.end()&&i<j;}
inline Status contact(const PoliticalOfficeResignationContext& x,const StableId& actor,const StableId& seat){auto valid=politics_detail::available(x.common,x.activity,actor);if(!valid.ok)return valid;const auto* person=x.common.actor(actor);const auto* location=person?std::get_if<SettlementLocation>(&person->location):nullptr;if(!location||location->place_id!=seat||x.activity.in_interaction(actor))return common_failure("PoliticalOfficeResignationLocalFreePersonRequired",actor);return growth_independent_office_age(x.common,actor);}
inline Status person_before(const PoliticalOfficeResignationContext& x,const StableId& actor,Integer tick,const StableId& fact){auto p=read_actor_presence_before_fact(x.common,x.common_catalog,x.death_origin,actor,tick,fact);if(!p.ok)return {false,{},p.error};const auto* a=x.common.state().actors.find(actor);if(!p.value.alive||!a||!a->birth_tick||*a->birth_tick>tick||*a->birth_tick< -2147483647||tick<0||tick>2147483647||tick-*a->birth_tick<18*720)return common_failure("PoliticalOfficeResignationHistoricalAdultRequired",actor);return common_success();}
inline Status current_jurisdiction(const PoliticalOfficeResignationContext& x,const PoliticalOfficeResignationPolicy& p,Integer expected){const auto* initial=x.politics_catalog.jurisdictions.find(p.jurisdiction_id);const auto* current=x.politics.jurisdictions.find(p.jurisdiction_id);if(!initial||!current||initial->revision!=0||current->revision!=expected||expected!=0||current->office_id!=initial->office_id||current->seat_place_id!=initial->seat_place_id||current->political_organization_id!=initial->political_organization_id||current->controlling_organization_id!=initial->political_organization_id)return common_failure("PoliticalOfficeResignationOriginalJurisdictionRequired",p.id);return x.seat(p,x.common.tick(),{});}
inline Status grant(const PoliticalOfficeResignationContext& x,const PoliticalOfficeResignationPolicy& p,Integer tick){const auto* head=x.successions.policies.find(p.approval_succession_policy_id);const auto* g=x.organization_catalog.grants.find(p.approval_grant_id);const auto* office=head?x.organization_catalog.offices.find(head->leader_office_id):nullptr;const auto* j=x.politics_catalog.jurisdictions.find(p.jurisdiction_id);if(!head||!g||!office||!j||g->office_id!=office->id||std::find(office->grant_ids.begin(),office->grant_ids.end(),g->id)==office->grant_ids.end()||tick<g->valid_from||(g->valid_until&&tick>*g->valid_until)||std::find(g->allowed_command_kinds.begin(),g->allowed_command_kinds.end(),political_office_resignation_answer_command)==g->allowed_command_kinds.end()||std::none_of(g->scopes.begin(),g->scopes.end(),[&](const ScopeRef& scope){return scope.kind==ScopeRef::Kind::site&&scope.id==head->seat_place_id;}))return common_failure("PoliticalOfficeResignationApprovalGrantRequired",p.id);return common_success();}
inline Status holder_before(const PoliticalOfficeResignationContext& x,const StableId& office,const StableId& actor,Integer epoch,Integer tick,const StableId& boundary){auto read=read_political_office_resignation_office_before(x.common,x.organizations,x.organization_catalog,office,tick,boundary);if(!read.ok)return {false,{},read.error};return read.value.holder_actor_id==std::optional<StableId>{actor}&&read.value.office_epoch==epoch?common_success():common_failure("PoliticalOfficeResignationOriginalTermRequired",boundary);}
inline Status holder_now(const PoliticalOfficeResignationContext& x,const StableId& office,const StableId& actor,Integer epoch){auto read=read_political_office_resignation_office(x.common,x.organizations,x.organization_catalog,office);if(!read.ok)return {false,{},read.error};const auto* current=x.organizations.offices.find(office);return current&&!current->deputy_actor_id&&read.value.holder_actor_id==std::optional<StableId>{actor}&&read.value.office_epoch==epoch?common_success():common_failure("PoliticalOfficeResignationOriginalTermRequired",office);}
}
